package com.bank.text;

class TextAnalyzer {

    // One pass: classify each LETTER as vowel or consonant; skip non-letters.
    LetterCount countVowelsAndConsonants(String s) {
        if (s == null) throw new IllegalArgumentException("null string");
        int vowels = 0, consonants = 0;
        String lower = s.toLowerCase();
        for (int i = 0; i < lower.length(); i++) {
            char c = lower.charAt(i);
            if (!Character.isLetter(c)) {
                continue;                       // skip digits, spaces, punctuation
            }
            if ("aeiou".indexOf(c) >= 0) {
                vowels++;                       // it is a vowel
            } else {
                consonants++;                   // any other letter is a consonant
            }
        }
        return new LetterCount(vowels, consonants);
    }
}
